from .camera_active_v2 import append_annotation, atomic_json, coco_base, hardlink_or_copy, sha256
from .camera_active_v5_negatives import CAMERA_ROOT, MANIFEST_ROOT, ROOT, read_csv


VARIANT_QUOTAS = {
    "real_only": {
        "real_positive": 560,
        "synthetic_positive": 0,
        "real_negative": 240,
        "synthetic_negative": 0,
    },
    "synth30": {
        "real_positive": 392,
        "synthetic_positive": 168,
