def _add_image(
    payload: dict[str, Any],
    metadata: dict[str, Any],
    bbox: tuple[float, float, float, float] | None,
) -> None:
    image_id = len(payload["images"]) + 1
    payload["images"].append({"id": image_id, **metadata})
    if bbox is not None:
        append_annotation(payload, len(payload["annotations"]) + 1, image_id, bbox)


def _image_size(path: Path) -> tuple[int, int]:
    with Image.open(path) as image:
        return image.size


def _copy_real_rows(
    split_rows: list[dict[str, str]],
    output_root: Path,
    coco: dict[str, dict[str, Any]],
) -> list[dict[str, str]]:
    freeze: list[dict[str, str]] = []
    for row in split_rows:
        split = row["dataset_split"]
        source = CAMERA_ROOT / row["raw_image_path"]
        annotation = json.loads((CAMERA_ROOT / row["annotation_path"]).read_text(encoding="utf-8"))
        destination_name = f"subjects/{row['anonymous_subject_id']}/{row['sample_id']}{source.suffix.lower()}"
        hardlink_or_copy(source, output_root / f"{split}2017" / destination_name)
        bbox_value = annotation.get("bbox") if row["status"] == "device" else None
        bbox = tuple(float(value) for value in bbox_value) if bbox_value else None
        group = "real_positive" if bbox is not None else "real_negative"
        _add_image(coco[split], {
            "file_name": destination_name,
            "width": int(row["width"]),
            "height": int(row["height"]),
            "source_group": group,
            "source_kind": "confirmed_camera_frame",
            "subject_id": row["anonymous_subject_id"],
            "session_id": row["session_id"],
            "source_video_id": row["source_video_id"],
            "sample_id": row["sample_id"],
            "source_sha256": row["sha256"],
        }, bbox)
        freeze.append({
            "sample_id": row["sample_id"],
            "split": split,
            "sha256": row["sha256"],
            "annotation_sha256": row["annotation_sha256"],
        })
    return freeze


def _copy_hard_negatives(output_root: Path, payload: dict[str, Any]) -> int:
    rows = read_csv(MANIFEST_ROOT / "hard_negative_approved.csv")
    for row in rows:
        source = Path(row["image_path"])
        name = f"hard_negative/{source.name}"
        hardlink_or_copy(source, output_root / "train2017" / name)
        width, height = _image_size(source)
        _add_image(payload, {
            "file_name": name,
            "width": width,
            "height": height,
            "source_group": "real_negative",
            "source_kind": "device_free_crop_outside_expanded_bbox",
            "subject_id": row["subject_id"],
            "sample_id": row["sample_id"],
            "source_sha256": row["source_sha256"],
            "derived_sha256": row["image_sha256"],
        }, None)
    return len(rows)


def _copy_synthetic_positives(output_root: Path, payload: dict[str, Any]) -> int:
    rows = read_csv(MANIFEST_ROOT / "synthetic_positive_train_eligible.csv")
    source_root = ROOT / "data/synthetic_device_clean_v1/images"
    for row in rows:
        source = source_root / row["filename"]
        name = f"synthetic_positive/{row['filename']}"
        hardlink_or_copy(source, output_root / "train2017" / name)
        width, height = _image_size(source)
        bbox = tuple(float(row[key]) for key in ("bbox_x1", "bbox_y1", "bbox_x2", "bbox_y2"))
        _add_image(payload, {
            "file_name": name,
            "width": width,
            "height": height,
            "source_group": "synthetic_positive",
            "source_kind": "quality_gated_copy_paste",
            "subject_id": row["source_subject"],
            "source_asset": row["source_asset"],
            "background_path": row["background_path"],
            "derived_sha256": row["sha256"],
        }, bbox)
    return len(rows)


def _copy_synthetic_negatives(output_root: Path, payload: dict[str, Any]) -> dict[str, int]:
    removed = read_csv(MANIFEST_ROOT / "device_removed_approved.csv")
    for row in removed:
        source = Path(row["image_path"])
        name = f"synthetic_negative/device_removed/{source.name}"
        hardlink_or_copy(source, output_root / "train2017" / name)
        width, height = _image_size(source)
        _add_image(payload, {
            "file_name": name,
            "width": width,
            "height": height,
            "source_group": "synthetic_negative",
            "source_kind": row["method"],
            "subject_id": row["subject_id"],
            "sample_id": row["sample_id"],
            "source_sha256": row["source_sha256"],
            "derived_sha256": row["image_sha256"],
        }, None)
    paired = read_csv(MANIFEST_ROOT / "paired_synthetic_negatives.csv")
    for row in paired:
        source = Path(row["image_path"])
        name = f"synthetic_negative/paired_background/{source.name}"
        hardlink_or_copy(source, output_root / "train2017" / name)
        width, height = _image_size(source)
        _add_image(payload, {
            "file_name": name,
            "width": width,
            "height": height,
            "source_group": "synthetic_negative",
            "source_kind": "exact_pre_composite_background",
            "subject_id": "background",
            "source_sha256": row["source_sha256"],
            "derived_sha256": row["image_sha256"],
        }, None)
    return {"device_removed": len(removed), "paired_background": len(paired)}


def _validate_payload(coco: dict[str, dict[str, Any]], variant: str) -> None:
    expected = {"train": 315, "val": 102, "test": 104}
    for split, minimum in expected.items():
        if split != "train" and len(coco[split]["images"]) != minimum:
            raise RuntimeError(f"{split} count mismatch")
    groups = Counter(image["source_group"] for image in coco["train"]["images"])
    required = {"real_positive", "real_negative"}
    if variant != "real_only":
        required |= {"synthetic_positive", "synthetic_negative"}
    missing = required - set(groups)
    if missing:
        raise RuntimeError(f"{variant} missing groups: {sorted(missing)}")
    if variant == "real_only" and (groups["synthetic_positive"] or groups["synthetic_negative"]):
        raise RuntimeError("REAL-ONLY contains synthetic data")
    split_sha = {
        split: {image.get("source_sha256") for image in payload["images"] if image.get("source_sha256")}
        for split, payload in coco.items()
    }
    if split_sha["train"] & split_sha["val"] or split_sha["train"] & split_sha["test"] or split_sha["val"] & split_sha["test"]:
        raise RuntimeError("source SHA leaked across V5 splits")


def export_variant(output_root: Path, variant: str) -> dict[str, Any]:
    if variant not in VARIANT_QUOTAS:
        raise ValueError(f"unknown V5 variant: {variant}")
    split_rows = read_csv(MANIFEST_ROOT / "fixed_split.csv")
    coco = {split: coco_base(f"CAMERA-ACTIVE-V5 {variant} {split}") for split in ("train", "val", "test")}
    freeze = _copy_real_rows(split_rows, output_root, coco)
    hard_count = _copy_hard_negatives(output_root, coco["train"])
    synthetic_positive_count = 0
    synthetic_negative_counts = {"device_removed": 0, "paired_background": 0}
    if variant != "real_only":
        synthetic_positive_count = _copy_synthetic_positives(output_root, coco["train"])
        synthetic_negative_counts = _copy_synthetic_negatives(output_root, coco["train"])
    _validate_payload(coco, variant)
    for split, payload in coco.items():
        atomic_json(output_root / f"annotations/instances_{split}2017.json", payload)
    counts = {
        split: {
            "images": len(payload["images"]),
            "annotations": len(payload["annotations"]),
            "source_groups": dict(Counter(str(image["source_group"]) for image in payload["images"])),
            "subjects": dict(Counter(str(image.get("subject_id", "")) for image in payload["images"])),
        }
        for split, payload in coco.items()
    }
    manifest = {
        "schema_version": 1,
        "dataset_id": f"camera_active_v5_{variant}",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "variant": variant,
        "seed": 42,
        "fixed_split_manifest": str(MANIFEST_ROOT / "fixed_split.csv"),
        "fixed_split_manifest_sha256": sha256(MANIFEST_ROOT / "fixed_split.csv"),
        "negative_quality_gate": str(ROOT / "reports/camera_active_v5/negative_quality_gate.json"),
        "negative_quality_gate_sha256": sha256(ROOT / "reports/camera_active_v5/negative_quality_gate.json"),
        "counts": counts,
        "samples_per_epoch": 800,
        "epoch_quotas": VARIANT_QUOTAS[variant],
        "hard_negative_count": hard_count,
        "synthetic_positive_count": synthetic_positive_count,
        "synthetic_negative_counts": synthetic_negative_counts,
        "real_positive_subject_balancing": "equal probability across four subjects",
        "test_policy": "fixed once; no derivatives in training; evaluated once after model selection",
        "frozen_records": freeze,
        "production_ready": False,
    }
    atomic_json(output_root / "dataset_manifest.json", manifest)
    return manifest
