"""CAMERA-ACTIVE-V5 grouped split and dataset invariants."""

from __future__ import annotations

import csv
import hashlib
import json
import random
from collections import Counter, defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable


SUBJECT_TARGETS = {
    "贝塔": {"train": 176, "val": 57, "test": 57},
    "凌川": {"train": 98, "val": 32, "test": 33},
    "帕斯卡": {"train": 17, "val": 5, "test": 6},
    "布尔": {"train": 24, "val": 8, "test": 8},
}
NO_DEVICE_TARGETS = {
    bytes.fromhex("e8b49de5a194").decode(): {"train": 4, "val": 1, "test": 2},
    bytes.fromhex("e5878ce5b79d").decode(): {"train": 1, "val": 1, "test": 0},
    bytes.fromhex("e5b895e696afe58da1").decode(): {"train": 0, "val": 0, "test": 0},
    bytes.fromhex("e5b883e5b094").decode(): {"train": 1, "val": 0, "test": 0},
}



class DisjointSet:
    def __init__(self, values: Iterable[str]):
        self.parent = {value: value for value in values}

    def find(self, value: str) -> str:
        parent = self.parent[value]
        if parent != value:
            self.parent[value] = self.find(parent)
        return self.parent[value]

    def union(self, left: str, right: str) -> None:
        left_root, right_root = self.find(left), self.find(right)
        if left_root != right_root:
            self.parent[right_root] = left_root


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(encoding="utf-8-sig", newline="") as stream:
        return list(csv.DictReader(stream))


def _frame_order(row: dict[str, str]) -> tuple[int, int, str]:
    def number(value: str) -> int:
        try:
            return int(float(value))
        except (TypeError, ValueError):
            return 10**18

    return number(row.get("video_frame_offset_ms", "")), number(row.get("frame_id", "")), row["sample_id"]


def load_confirmed_samples(camera_root: Path) -> list[dict[str, str]]:
    rows = _read_csv(camera_root / "manifests/samples.csv")
    confirmed = [
        dict(row)
        for row in rows
        if row.get("review_state") == "confirmed"
        and row.get("annotation_state") == "confirmed"
        and not row.get("deleted_at")
    ]
    if len(confirmed) != 521:
        raise RuntimeError(f"expected 521 confirmed samples, got {len(confirmed)}")
    for row in confirmed:
        row["raw_path_absolute"] = str((camera_root / row["raw_image_path"]).resolve())
        row["annotation_path_absolute"] = str((camera_root / row["annotation_path"]).resolve())
        annotation = json.loads(Path(row["annotation_path_absolute"]).read_text(encoding="utf-8"))
        if annotation.get("status") != row.get("status"):
            raise RuntimeError(f"status mismatch: {row['sample_id']}")
        if annotation.get("raw_sha256") and annotation["raw_sha256"] != row["sha256"]:
            raise RuntimeError(f"annotation SHA mismatch: {row['sample_id']}")
        if sha256_file(Path(row["raw_path_absolute"])) != row["sha256"]:
            raise RuntimeError(f"raw SHA mismatch: {row['sample_id']}")
    return confirmed


def _stable_seed(seed: int, subject: str, stage: str) -> int:
    value = hashlib.sha256(f"{seed}:{subject}:{stage}".encode()).digest()
    return int.from_bytes(value[:8], "big")


def _choose_exact(groups: list[list[dict[str, str]]], target: int, seed: int) -> set[str]:
    shuffled = list(groups)
    random.Random(seed).shuffle(shuffled)
    shuffled.sort(key=lambda group: not any(row["status"] == "no_device" for row in group))
    states: dict[int, tuple[int, ...]] = {0: ()}
    for index, group in enumerate(shuffled):
        size = len(group)
        for current, selected in sorted(list(states.items()), reverse=True):
            total = current + size
            if total <= target and total not in states:
                states[total] = (*selected, index)
    if target not in states:
        available = sorted(states, key=lambda value: (abs(target - value), -value))[:8]
        raise RuntimeError(f"cannot satisfy grouped target={target}; closest={available}")
    return {
        row["sample_id"]
        for index in states[target]
        for row in shuffled[index]
    }


def build_grouped_split(rows: list[dict[str, str]], seed: int = 42, block_size: int = 1) -> list[dict[str, str]]:
    by_subject: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        by_subject[row["anonymous_subject_id"]].append(row)
    if set(by_subject) != set(SUBJECT_TARGETS):
        raise RuntimeError(f"unexpected subjects: {sorted(by_subject)}")

    assignments: dict[str, str] = {}
    group_ids: dict[str, str] = {}
    for subject, subject_rows in by_subject.items():
        dsu = DisjointSet(row["sample_id"] for row in subject_rows)
        by_video: dict[str, list[dict[str, str]]] = defaultdict(list)
        for row in subject_rows:
            by_video[row.get("source_video_id") or row["session_id"]].append(row)
        for video_rows in by_video.values():
            ordered = sorted(video_rows, key=_frame_order)
            for start in range(0, len(ordered), block_size):
                block = ordered[start : start + block_size]
                for row in block[1:]:
                    dsu.union(block[0]["sample_id"], row["sample_id"])
        for field in ("sha256", "duplicate_group"):
            values: dict[str, list[str]] = defaultdict(list)
            for row in subject_rows:
                value = row.get(field, "")
                if value:
                    values[value].append(row["sample_id"])
            for members in values.values():
                for member in members[1:]:
                    dsu.union(members[0], member)

        grouped: dict[str, list[dict[str, str]]] = defaultdict(list)
        for row in subject_rows:
            grouped[dsu.find(row["sample_id"])].append(row)
        groups = list(grouped.values())
        forced_train = [group for group in groups if any(row.get("capture_view") == "product" for row in group)]
        candidates = [group for group in groups if group not in forced_train]
        negative_groups = [group for group in candidates if all(row["status"] == "no_device" for row in group)]
        positive_groups = [group for group in candidates if all(row["status"] == "device" for row in group)]
        if len(negative_groups) + len(positive_groups) != len(candidates):
            raise RuntimeError(f"mixed device/no_device duplicate group for {subject}")
        negative_targets = NO_DEVICE_TARGETS[subject]
        test_negative_ids = _choose_exact(
            negative_groups, negative_targets["test"], _stable_seed(seed, subject, "test-negative")
        )
        remaining_negative = [
            group for group in negative_groups
            if not any(row["sample_id"] in test_negative_ids for row in group)
        ]
        val_negative_ids = _choose_exact(
            remaining_negative, negative_targets["val"], _stable_seed(seed, subject, "val-negative")
        )
        test_positive_ids, val_positive_ids = _choose_two_exact(
            positive_groups,
            SUBJECT_TARGETS[subject]["test"] - negative_targets["test"],
            SUBJECT_TARGETS[subject]["val"] - negative_targets["val"],
            _stable_seed(seed, subject, "test-val"),
        )
        test_ids = test_negative_ids | test_positive_ids
        val_ids = val_negative_ids | val_positive_ids
        for group in groups:
            digest = hashlib.sha256("\n".join(sorted(row["sample_id"] for row in group)).encode()).hexdigest()[:16]
            for row in group:
                sample_id = row["sample_id"]
                group_ids[sample_id] = f"{subject}_{digest}"
                assignments[sample_id] = "test" if sample_id in test_ids else "val" if sample_id in val_ids else "train"

    output = []
    for row in rows:
        record = dict(row)
        record["dataset_split"] = assignments[row["sample_id"]]
        record["split_group_id"] = group_ids[row["sample_id"]]
        record["split_seed"] = str(seed)
        record["annotation_sha256"] = sha256_file(Path(row["annotation_path_absolute"]))
        output.append(record)
    validate_split(output)
    return output


def validate_split(rows: list[dict[str, str]]) -> None:
    if len(rows) != 521 or len({row["sample_id"] for row in rows}) != 521:
        raise RuntimeError("V5 split must contain 521 unique sample IDs")
    for subject, targets in SUBJECT_TARGETS.items():
        counts = Counter(row["dataset_split"] for row in rows if row["anonymous_subject_id"] == subject)
        if dict(counts) != targets:
            raise RuntimeError(f"split mismatch for {subject}: {dict(counts)} != {targets}")
    for key in ("split_group_id", "sha256"):
        seen: dict[str, set[str]] = defaultdict(set)
        for row in rows:
            seen[row[key]].add(row["dataset_split"])
        leaked = [value for value, splits in seen.items() if len(splits) > 1]
        if leaked:
            raise RuntimeError(f"{key} leaked across split: {leaked[:5]}")
    product_splits = {row["dataset_split"] for row in rows if row.get("capture_view") == "product"}
    if product_splits != {"train"}:
        raise RuntimeError(f"product images must remain train-only: {product_splits}")


def write_split(camera_root: Path, output_root: Path, seed: int = 42) -> dict[str, object]:
    rows = build_grouped_split(load_confirmed_samples(camera_root), seed=seed)
    output_root.mkdir(parents=True, exist_ok=True)
    fields = [
        "sample_id", "anonymous_subject_id", "session_id", "source_video_id", "split_group_id",
        "dataset_split", "status", "contact_visibility", "capture_view", "raw_image_path",
        "annotation_path", "width", "height", "sha256", "annotation_sha256", "perceptual_hash",
        "duplicate_group", "video_frame_offset_ms", "frame_id", "split_seed",
    ]
    manifest_path = output_root / "fixed_split.csv"
    with manifest_path.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields)
        writer.writeheader()
        writer.writerows({field: row.get(field, "") for field in fields} for row in rows)
    counts = {
        subject: dict(Counter(row["dataset_split"] for row in rows if row["anonymous_subject_id"] == subject))
        for subject in SUBJECT_TARGETS
    }
    status_counts = {
        split: dict(Counter(row["status"] for row in rows if row["dataset_split"] == split))
        for split in ("train", "val", "test")
    }
    summary = {
        "schema_version": 1,
        "dataset_id": "camera_active_v5_fixed_split",
        "seed": seed,
        "block_size": 1,
        "counts_by_subject": counts,
        "status_counts": status_counts,
        "manifest_sha256": sha256_file(manifest_path),
        "same_session_limitation": "Pascal and Boolean each have one video; this split is not an unseen-subject test.",
        "production_ready": False,
    }
    (output_root / "fixed_split.json").write_text(json.dumps(summary, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return summary
def _choose_two_exact(
    groups: list[list[dict[str, str]]],
    first_target: int,
    second_target: int,
    seed: int,
) -> tuple[set[str], set[str]]:
    """Assign indivisible groups to two splits without greedy starvation."""
    shuffled = list(groups)
    random.Random(seed).shuffle(shuffled)
    shuffled.sort(key=lambda group: not any(row["status"] == "no_device" for row in group))
    states: dict[tuple[int, int], tuple[tuple[int, str], ...]] = {(0, 0): ()}
    for index, group in enumerate(shuffled):
        size = len(group)
        additions: dict[tuple[int, int], tuple[tuple[int, str], ...]] = {}
        for (first, second), selected in list(states.items()):
            if first + size <= first_target:
                additions.setdefault((first + size, second), (*selected, (index, "first")))
            if second + size <= second_target:
                additions.setdefault((first, second + size), (*selected, (index, "second")))
        for state, selected in additions.items():
            states.setdefault(state, selected)
    target = (first_target, second_target)
    if target not in states:
        closest = sorted(
            states,
            key=lambda value: (
                abs(first_target - value[0]) + abs(second_target - value[1]),
                -(value[0] + value[1]),
            ),
        )[:8]
        raise RuntimeError(f"cannot satisfy grouped targets={target}; closest={closest}")
    first_ids: set[str] = set()
    second_ids: set[str] = set()
    for index, split_name in states[target]:
        destination = first_ids if split_name == "first" else second_ids
        destination.update(row["sample_id"] for row in shuffled[index])
    return first_ids, second_ids


