def _add_image(
    payload: dict[str, Any],
    metadata: dict[str, Any],
    bbox: tuple[float, float, float, float] | None,
) -> None:
    image_id = len(payload["images"]) + 1
    payload["images"].append({"id": image_id, **metadata})
    if bbox is not None:
        append_annotation(payload, len(payload["annotations"]) + 1, image_id, bbox)


def _image_size(path: Path) -> tuple[int, int]:
    with Image.open(path) as image:
        return image.size


def _copy_real_rows(
    split_rows: list[dict[str, str]],
    output_root: Path,
    coco: dict[str, dict[str, Any]],
) -> list[dict[str, str]]:
    freeze: list[dict[str, str]] = []
    for row in split_rows:
        split = row["dataset_split"]
        source = CAMERA_ROOT / row["raw_image_path"]
        annotation = json.loads((CAMERA_ROOT / row["annotation_path"]).read_text(encoding="utf-8"))
        destination_name = f"subjects/{row['anonymous_subject_id']}/{row['sample_id']}{source.suffix.lower()}"
        hardlink_or_copy(source, output_root / f"{split}2017" / destination_name)
        bbox_value = annotation.get("bbox") if row["status"] == "device" else None
        bbox = tuple(float(value) for value in bbox_value) if bbox_value else None
        group = "real_positive" if bbox is not None else "real_negative"
        _add_image(coco[split], {
            "file_name": destination_name,
            "width": int(row["width"]),
            "height": int(row["height"]),
            "source_group": group,
            "source_kind": "confirmed_camera_frame",
            "subject_id": row["anonymous_subject_id"],
            "session_id": row["session_id"],
            "source_video_id": row["source_video_id"],
            "sample_id": row["sample_id"],
            "source_sha256": row["sha256"],
        }, bbox)
        freeze.append({
            "sample_id": row["sample_id"],
            "split": split,
            "sha256": row["sha256"],
            "annotation_sha256": row["annotation_sha256"],
        })
    return freeze


def _copy_hard_negatives(output_root: Path, payload: dict[str, Any]) -> int:
    rows = read_csv(MANIFEST_ROOT / "hard_negative_approved.csv")
    for row in rows:
        source = Path(row["image_path"])
        name = f"hard_negative/{source.name}"
        hardlink_or_copy(source, output_root / "train2017" / name)
        width, height = _image_size(source)
        _add_image(payload, {
            "file_name": name,
            "width": width,
            "height": height,
            "source_group": "real_negative",
            "source_kind": "device_free_crop_outside_expanded_bbox",
            "subject_id": row["subject_id"],
            "sample_id": row["sample_id"],
            "source_sha256": row["source_sha256"],
            "derived_sha256": row["image_sha256"],
        }, None)
    return len(rows)


def _copy_synthetic_positives(output_root: Path, payload: dict[str, Any]) -> int:
    rows = read_csv(MANIFEST_ROOT / "synthetic_positive_train_eligible.csv")
    source_root = ROOT / "data/synthetic_device_clean_v1/images"
    for row in rows:
        source = source_root / row["filename"]
        name = f"synthetic_positive/{row['filename']}"
