            "source_group": "synthetic_negative",
            "source_kind": "exact_pre_composite_background",
            "subject_id": "background",
            "source_sha256": row["source_sha256"],
            "derived_sha256": row["image_sha256"],
        }, None)
    return {"device_removed": len(removed), "paired_background": len(paired)}


def _validate_payload(coco: dict[str, dict[str, Any]], variant: str) -> None:
    expected = {"train": 315, "val": 102, "test": 104}
    for split, minimum in expected.items():
        if split != "train" and len(coco[split]["images"]) != minimum:
            raise RuntimeError(f"{split} count mismatch")
    groups = Counter(image["source_group"] for image in coco["train"]["images"])
    required = {"real_positive", "real_negative"}
    if variant != "real_only":
        required |= {"synthetic_positive", "synthetic_negative"}
    missing = required - set(groups)
    if missing:
        raise RuntimeError(f"{variant} missing groups: {sorted(missing)}")
    if variant == "real_only" and (groups["synthetic_positive"] or groups["synthetic_negative"]):
        raise RuntimeError("REAL-ONLY contains synthetic data")
    split_sha = {
        split: {image.get("source_sha256") for image in payload["images"] if image.get("source_sha256")}
        for split, payload in coco.items()
    }
    if split_sha["train"] & split_sha["val"] or split_sha["train"] & split_sha["test"] or split_sha["val"] & split_sha["test"]:
        raise RuntimeError("source SHA leaked across V5 splits")


def export_variant(output_root: Path, variant: str) -> dict[str, Any]:
    if variant not in VARIANT_QUOTAS:
        raise ValueError(f"unknown V5 variant: {variant}")
    split_rows = read_csv(MANIFEST_ROOT / "fixed_split.csv")
    coco = {split: coco_base(f"CAMERA-ACTIVE-V5 {variant} {split}") for split in ("train", "val", "test")}
    freeze = _copy_real_rows(split_rows, output_root, coco)
    hard_count = _copy_hard_negatives(output_root, coco["train"])
    synthetic_positive_count = 0
    synthetic_negative_counts = {"device_removed": 0, "paired_background": 0}
    if variant != "real_only":
        synthetic_positive_count = _copy_synthetic_positives(output_root, coco["train"])
        synthetic_negative_counts = _copy_synthetic_negatives(output_root, coco["train"])
    _validate_payload(coco, variant)
    for split, payload in coco.items():
        atomic_json(output_root / f"annotations/instances_{split}2017.json", payload)
    counts = {
        split: {
            "images": len(payload["images"]),
            "annotations": len(payload["annotations"]),
            "source_groups": dict(Counter(str(image["source_group"]) for image in payload["images"])),
            "subjects": dict(Counter(str(image.get("subject_id", "")) for image in payload["images"])),
        }
        for split, payload in coco.items()
    }
    manifest = {
        "schema_version": 1,
        "dataset_id": f"camera_active_v5_{variant}",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "variant": variant,
        "seed": 42,
        "fixed_split_manifest": str(MANIFEST_ROOT / "fixed_split.csv"),
        "fixed_split_manifest_sha256": sha256(MANIFEST_ROOT / "fixed_split.csv"),
        "negative_quality_gate": str(ROOT / "reports/camera_active_v5/negative_quality_gate.json"),
        "negative_quality_gate_sha256": sha256(ROOT / "reports/camera_active_v5/negative_quality_gate.json"),
        "counts": counts,
        "samples_per_epoch": 800,
        "epoch_quotas": VARIANT_QUOTAS[variant],
        "hard_negative_count": hard_count,
        "synthetic_positive_count": synthetic_positive_count,
        "synthetic_negative_counts": synthetic_negative_counts,
        "real_positive_subject_balancing": "equal probability across four subjects",
        "test_policy": "fixed once; no derivatives in training; evaluated once after model selection",
        "frozen_records": freeze,
        "production_ready": False,
    }
    atomic_json(output_root / "dataset_manifest.json", manifest)
    return manifest

