    @property
    def dataset_split_path(self) -> Path:
        return self.manifest_root / "dataset_split_v1.csv"

    @property
    def subject_registry_path(self) -> Path:
        return self.manifest_root / "subjects.json"

    def _registered_subjects(self) -> list[str]:
        if not self.subject_registry_path.exists():
            return []
        payload = json.loads(self.subject_registry_path.read_text(encoding="utf-8"))
        values = payload.get("subjects", []) if isinstance(payload, dict) else []
        return [self._normalise_subject_id(str(value)) for value in values]

    def list_subjects(self) -> dict[str, Any]:
        with self._lock:
            subjects: list[str] = []

            def add(value: Any) -> None:
                try:
                    subject = self._normalise_subject_id(str(value or ""))
                except ValueError:
                    return
                if subject not in subjects:
                    subjects.append(subject)

            for value in ("\u8d1d\u5854", "\u51cc\u5ddd", "\u5e15\u65af\u5361", "\u5e03\u5c14"):
                add(value)
            for value in self._registered_subjects():
                add(value)
            for row in self._rows():
                add(row.get("anonymous_subject_id"))
            for row in _read_csv(self.manifest_root / "sessions.csv"):
                add(row.get("anonymous_subject_id"))
            return {"subjects": subjects, "count": len(subjects)}

