            rows = [self._public_row(row, split_map) for row in self._rows()]
            if review_state and review_state != "all":
                rows = [row for row in rows if row.get("review_state") == review_state]
            if split and split != "all":
                rows = [row for row in rows if row.get("split") == split]
            if subject_id and subject_id != "all":
                rows = [
                    row for row in rows
                    if row.get("anonymous_subject_id") == subject_id
                ]
            if status and status != "all":
                rows = [row for row in rows if row.get("status") == status]
            if quality and quality != "all":
                def matches(row: dict[str, str]) -> bool:
                    warnings = json.loads(row.get("quality_warnings") or "[]")
                    if quality == "near_duplicate":
                        return bool(row.get("nearest_sample_id")) and str(row.get("nearest_phash_distance", "")).isdigit() and int(row["nearest_phash_distance"]) <= self.phash_distance
                    if quality == "blurry":
                        return "image_blurry" in warnings
                    if quality == "missing_contact":
                        return "missing_contact" in warnings
                    return True
                rows = [row for row in rows if matches(row)]
            rows.sort(key=lambda row: row.get("captured_at", ""), reverse=True)
            total = len(rows)
            limit = max(1, min(int(limit), 1000))
            offset = max(0, int(offset))
            return {
                "items": rows[offset:offset + limit],
                "total": total,
                "limit": limit,
                "offset": offset,
            }

    def sample_detail(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            _, row, _ = self._row(sample_id)
            annotation = _json_load(self._path(row["annotation_path"]))
            prediction = _json_load(self._path(row["prediction_snapshot_path"]))
            annotation.setdefault("review_state", row.get("review_state", "confirmed"))
            annotation.setdefault("status", row.get("status", "device"))
            annotation.setdefault(
                "review_revision",
                int(row.get("review_revision") or (
                    1 if row.get("review_state") == "confirmed" else 0
                )),
            )
            annotation.setdefault("review_history", [])
            split_map = self._dataset_split_map()
            public_row = self._public_row(row, split_map)
            annotation.setdefault("dataset_split", public_row["dataset_split"])
            return {"sample": public_row, "annotation": annotation, "prediction": prediction}

    def image_path(self, sample_id: str) -> Path:
        with self._lock:
            _, row, _ = self._row(sample_id)
            return self._path(row["raw_image_path"])

