            final_subject = self._normalise_subject_id(
                str(payload.get("anonymous_subject_id") or row["anonymous_subject_id"])
            )
            annotation_path = self._path(row["annotation_path"])
            annotation = _json_load(annotation_path)
            now = _now()
            previous_revision = int(
                annotation.get("review_revision") or (
                    1 if annotation.get("review_state") == "confirmed" else 0
                )
            )
            history = list(annotation.get("review_history") or [])
            history.append({
                "review_revision": previous_revision,
                "status": annotation.get("status"),
                "sample_kind": annotation.get("sample_kind"),
                "bbox": annotation.get("bbox"),
                "contact_point": annotation.get("contact_point"),
