    if (!data.ok) throw new Error(data.error || "读取模型版本失败");
    renderModelProfile(data.model_profile);
    const count = data.model_profile?.available?.length || 0;
    status("模型版本列表已刷新，共发现 " + count + " 个可切换组合。");
  } catch (error) {
    status("刷新模型版本失败：" + error.message, true);
  } finally {
    refreshModelProfilesBtn.disabled = false;
  }
}

async function switchModelProfile() {
  if (modelSwitching) return;
  modelSwitching = true;
  applyModelProfileBtn.disabled = true;
  modelProfileSelect.disabled = true;
  status("正在加载并校验模型组合，请稍候；当前跟踪将安全清空。");
  try {
    const response = await fetch("/v1/runtime/model-profile", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({profile: modelProfileSelect.value}),
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    latest = null;
    latestInferencePair = null;
    latestReceivedAt = 0;
    boxSamples = [];
    pointSamples = [];
    renderModelProfile(data.model_profile);
    status("模型组合切换成功，旧跟踪记忆已清空；请重新框选或等待自动搜索。");
  } catch (error) {
    status("模型切换失败：" + error.message, true);
    try {
      const response = await fetch("/v1/runtime/model-profile");
      const data = await response.json();
      if (data.ok) renderModelProfile(data.model_profile);
    } catch (_) {
      // Keep the last visible profile when status refresh also fails.
    }
  } finally {
    modelSwitching = false;
    applyModelProfileBtn.disabled = false;
    modelProfileSelect.disabled = false;
  }
}

function applyModes(modes) {
  manualEnabled = Boolean(modes.enable_manual_bbox_assist);
  markerEnabled = Boolean(modes.enable_marker_assist);
  setBadge("#manual-mode", "手动画框", manualEnabled);
  setBadge("#marker-mode", "AprilTag", markerEnabled);
  document.querySelectorAll(".manual-control").forEach((element) => {
    element.classList.toggle("hidden", !manualEnabled);
  });
  freezeBtn.disabled = !media || !manualEnabled;
  if (!manualEnabled && frozen) cancelSelection();
}

async function updateModes(nextManual, nextMarker) {
  manualModeBtn.disabled = true;
  markerModeBtn.disabled = true;
  try {
    const response = await fetch("/v1/assist/modes", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({
        enable_manual_bbox_assist: nextManual,
        enable_marker_assist: nextMarker,
      }),
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    applyModes(data.assist_modes);
    status("辅助模式已更新：手动画框" + (manualEnabled ? "开启" : "关闭") +
      "，AprilTag" + (markerEnabled ? "开启" : "关闭") + "。");
  } catch (error) {
    status("辅助模式更新失败：" + error.message, true);
  } finally {
    manualModeBtn.disabled = false;
    markerModeBtn.disabled = false;
  }
}

function fit() {
  if (!video.videoWidth) return;
  for (const target of [canvas, capture, seed]) {
    if (target.width !== video.videoWidth || target.height !== video.videoHeight) {
      target.width = video.videoWidth;
      target.height = video.videoHeight;
    }
  }
}

function validBox(box) {
  return Array.isArray(box) && box.length === 4 &&
    box.every(Number.isFinite) && box[2] > box[0] && box[3] > box[1];
}

function validPoint(point) {
  return Array.isArray(point) && point.length === 2 && point.every(Number.isFinite);
}

function rememberResult(result, receivedAt) {
  latest = result;
  latestReceivedAt = receivedAt;
  if (result.state === "TRACKING" && validBox(result.device_bbox)) {
    boxSamples.push({time: receivedAt, value: result.device_bbox.map(Number)});
    boxSamples = boxSamples.slice(-2);
    if (validPoint(result.contact_point) &&
        result.contact_visibility !== "not_annotatable" &&
        (result.contact_updated !== false || pointSamples.length === 0)) {
      pointSamples.push({time: receivedAt, value: result.contact_point.map(Number)});
      pointSamples = pointSamples.slice(-2);
    }
  } else if (result.state === "LOST" || result.state === "SEARCHING") {
    boxSamples = [];
    pointSamples = [];
  } else if (result.state === "UNCERTAIN") {
    pointSamples = [];
  }
}

function interpolateSamples(samples, now, kind) {
  if (!samples.length) return null;
  const current = samples[samples.length - 1];
  if (now - current.time > MAX_OVERLAY_AGE_MS) return null;
  if (samples.length === 1 || latest?.state !== "TRACKING") return current.value.slice();

  const previous = samples[samples.length - 2];
  const targetTime = now - INTERPOLATION_DELAY_MS;
  const duration = Math.max(current.time - previous.time, 1);
  if (targetTime <= current.time) {
    const alpha = Math.max(0, Math.min(1, (targetTime - previous.time) / duration));
    return current.value.map((value, index) =>
      previous.value[index] + (value - previous.value[index]) * alpha);
  }

  const extra = Math.min(targetTime - current.time, MAX_EXTRAPOLATION_MS);
  const factor = extra / duration;
  const limit = kind === "box"
    ? Math.max(current.value[2] - current.value[0], current.value[3] - current.value[1]) * 0.15
    : Math.min(canvas.width, canvas.height) * 0.025;
  return current.value.map((value, index) => {
    const movement = (value - previous.value[index]) * factor;
    return value + Math.max(-limit, Math.min(limit, movement));
  });
}

function drawBox(box, color, label, width = 6, dashed = false) {
  if (!validBox(box)) return;
  const [x1, y1, x2, y2] = box;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.setLineDash(dashed ? [14, 8] : []);
  ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
  ctx.setLineDash([]);
  ctx.fillStyle = color;
  ctx.font = "bold 20px sans-serif";
  ctx.fillText(label, x1 + 6, Math.max(24, y1 + 24));
  ctx.restore();
}

function drawPoint(point) {
  if (!validPoint(point)) return;
  const [x, y] = point;
  const radius = Math.max(12, Math.min(canvas.width, canvas.height) * 0.017);
  ctx.save();
  ctx.strokeStyle = "#f34ca8";
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x - radius - 7, y);
  ctx.lineTo(x + radius + 7, y);
  ctx.moveTo(x, y - radius - 7);
  ctx.lineTo(x, y + radius + 7);
  ctx.stroke();
  ctx.restore();
}

function drawMarkers(markers) {
  for (const marker of markers || []) {
    const points = marker.corners || [];
    if (points.length !== 4) continue;
    ctx.save();
    ctx.strokeStyle = "#18a56f";
    ctx.fillStyle = "#18a56f";
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let index = 1; index < 4; index += 1) ctx.lineTo(points[index][0], points[index][1]);
    ctx.closePath();
    ctx.stroke();
    ctx.font = "bold 22px sans-serif";
    ctx.fillText("Tag " + marker.marker_id, points[0][0] + 5, Math.max(24, points[0][1] - 8));
    ctx.restore();
  }
}

