#include "medvision/face_landmarker.hpp"

#include <limits>
#include <stdexcept>
#include <utility>

#include "mediapipe/tasks/c/core/common.h"
#include "mediapipe/tasks/c/vision/core/image.h"
#include "mediapipe/tasks/c/vision/face_landmarker/face_landmarker.h"

namespace medvision {
namespace {

std::runtime_error media_pipe_error(const std::string& operation, MpStatus status, char* message) {
    std::string detail = message == nullptr ? "no error detail" : message;
    if (message != nullptr) {
        MpErrorFree(message);
    }
    return std::runtime_error(
        operation + " failed (status=" + std::to_string(static_cast<int>(status)) + "): " + detail);
}

}  // namespace

struct FaceLandmarker::Impl {
    MpFaceLandmarkerPtr handle{};

    ~Impl() {
        if (handle != nullptr) {
            char* error = nullptr;
            MpFaceLandmarkerClose(handle, &error);
            if (error != nullptr) {
                MpErrorFree(error);
            }
        }
    }
};

FaceLandmarker::FaceLandmarker(const std::string& model_path) : impl_(std::make_unique<Impl>()) {
    FaceLandmarkerOptions options{};
    options.base_options.model_asset_path = model_path.c_str();
    options.base_options.delegate = CPU;
    options.base_options.host_environment = HOST_ENVIRONMENT_UNKNOWN;
    options.base_options.host_system = HOST_SYSTEM_LINUX;
    options.running_mode = IMAGE;
    options.num_faces = 1;
    options.min_face_detection_confidence = 0.5F;
    options.min_face_presence_confidence = 0.5F;
    options.min_tracking_confidence = 0.5F;

    char* error = nullptr;
    const auto status = MpFaceLandmarkerCreate(&options, &impl_->handle, &error);
    if (status != kMpOk) {
        throw media_pipe_error("MpFaceLandmarkerCreate", status, error);
    }
}

FaceLandmarker::~FaceLandmarker() = default;
FaceLandmarker::FaceLandmarker(FaceLandmarker&&) noexcept = default;
FaceLandmarker& FaceLandmarker::operator=(FaceLandmarker&&) noexcept = default;

std::vector<Point2f> FaceLandmarker::detect_rgb(
    const std::uint8_t* pixels,
    int width,
    int height,
    std::size_t byte_count) {
    if (pixels == nullptr || width <= 0 || height <= 0) {
        throw std::invalid_argument("face input image is empty");
    }
    if (byte_count != static_cast<std::size_t>(width) * static_cast<std::size_t>(height) * 3U
        || byte_count > static_cast<std::size_t>(std::numeric_limits<int>::max())) {
        throw std::invalid_argument("face input must be tightly packed RGB");
    }

    MpImagePtr image{};
    char* error = nullptr;
    auto status = MpImageCreateFromUint8Data(
        kMpImageFormatSrgb,
        width,
        height,
        pixels,
        static_cast<int>(byte_count),
        &image,
        &error);
    if (status != kMpOk) {
        throw media_pipe_error("MpImageCreateFromUint8Data", status, error);
    }

    FaceLandmarkerResult result{};
