                "updated_at": now,
            })
            warnings = [
                warning for warning in annotation.get("quality_warnings", [])
                if warning != "missing_contact"
            ]
            if (
                status == "device"
                and point is None
                and visibility not in {"not_in_contact", "not_annotatable"}
            ):
                warnings.append("missing_contact")
            annotation["quality_warnings"] = warnings
            _atomic(
                annotation_path,
                json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"),
            )
            _atomic(
                self._path(row["yolo_label_path"]),
                self._yolo(bbox, width, height, "confirmed").encode("ascii"),
            )
            self._write_preview(image, bbox, point, self._path(row["preview_path"]))
            row.update({
                "anonymous_subject_id": final_subject,
                "status": status,
                "sample_kind": kind,
                "contact_visibility": visibility,
                "review_state": "confirmed",
                "annotation_state": "confirmed",
                "quality_warnings": json.dumps(warnings, ensure_ascii=False),
                "review_revision": next_revision,
                "updated_at": now,
                "deleted_at": "",
            })
            rows[index] = row
            self._rewrite(rows)
            self._sync_subject_view(
                row, self._dataset_split_map().get(row["sample_id"], row.get("split", "train"))
            )
            return {"ok": True, "message": "人工审查结果已保存", "sample": row, "status": self.status()}

    @staticmethod
    def _write_preview(
        image: Image.Image,
        bbox: list[float] | None,
        point: list[float] | None,
        path: Path,
    ) -> None:
        preview = image.copy()
        draw = ImageDraw.Draw(preview)
        if bbox:
            draw.rectangle(tuple(bbox), outline=(32, 210, 112), width=6)
        if point:
            x, y = point
            radius = max(8, min(image.size) // 70)
            draw.ellipse((x - radius, y - radius, x + radius, y + radius), outline=(0, 220, 255), width=5)
            draw.line((x - radius * 2, y, x + radius * 2, y), fill=(0, 220, 255), width=4)
            draw.line((x, y - radius * 2, x, y + radius * 2), fill=(0, 220, 255), width=4)
        stream = io.BytesIO()
        preview.save(stream, format="JPEG", quality=92)
        _atomic(path, stream.getvalue())

    def delete(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            index, row, rows = self._row(sample_id)
            if row.get("review_state") == "deleted":
                return {"ok": True, "message": "样本已经处于删除状态", "sample": row}
            now = _now()
            row.update({
                "review_state": "deleted",
                "annotation_state": "deleted",
                "updated_at": now,
                "deleted_at": now,
            })
            annotation = _json_load(self._path(row["annotation_path"]))
            annotation.update({"review_state": "deleted", "annotation_state": "deleted", "deleted_at": now, "updated_at": now})
            _atomic(self._path(row["annotation_path"]), json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"))
            _atomic(self._path(row["yolo_label_path"]), b"")
            rows[index] = row
            self._rewrite(rows)
            return {"ok": True, "message": "样本已软删除，可在已删除筛选中恢复", "sample": row, "status": self.status()}

    def restore(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            index, row, rows = self._row(sample_id)
            if row.get("review_state") != "deleted":
                raise ValueError("只有已删除样本可以恢复")
            now = _now()
            row.update({
                "review_state": "pending_review",
                "annotation_state": "pending_review",
                "updated_at": now,
                "deleted_at": "",
            })
            annotation = _json_load(self._path(row["annotation_path"]))
            annotation.update({"review_state": "pending_review", "annotation_state": "pending_review", "deleted_at": "", "updated_at": now})
            _atomic(self._path(row["annotation_path"]), json.dumps(annotation, ensure_ascii=False, indent=2).encode("utf-8"))
            rows[index] = row
            self._rewrite(rows)
            return {"ok": True, "message": "样本已恢复到待审查队列", "sample": row, "status": self.status()}

    def status(self) -> dict[str, Any]:
        split_map = self._dataset_split_map()
