            "duplicate_of": item["duplicate_of"],
            "updated_at": _now(),
        })
    queue_path = manifest_root / "review_queue.csv"
    _write_csv(queue_path, queue_rows, QUEUE_FIELDS)
    lock = {
        "schema_version": 1,
        "dataset_manifest_sha256": hashlib.sha256(manifest_path.read_bytes()).hexdigest(),
        "review_queue_sha256": hashlib.sha256(queue_path.read_bytes()).hexdigest(),
        "source_count": len(frozen_rows),
        "queue_count": len(queue_rows),
        "review_gate": f"{len(queue_rows)}/{len(queue_rows)} confirmed",
    }
    _atomic(
        manifest_root / "dataset_lock.json",
        (json.dumps(lock, ensure_ascii=False, indent=2) + "\n").encode("utf-8"),
    )
    return {
        "manifest": str(manifest_path),
        "queue": str(queue_path),
        "source_count": len(frozen_rows),
        "unique_sha256_count": len(canonical_sha),
        "queue_count": len(queue_rows),
        "split_counts": dict(Counter(str(row["logical_split"]) for row in frozen_rows)),
        "subject_counts": dict(Counter(str(row["anonymous_subject_id"]) for row in frozen_rows)),
    }


class ContactFaceV6ReviewStore:
    def __init__(self, project_root: Path) -> None:
        self.project_root = project_root.resolve()
        self.camera_root = self.project_root / "data" / "camera_active_v1"
        self.data_root = self.project_root / "data" / "contact_face_v6"
        self.queue_path = self.project_root / "manifests" / "contact_face_v6" / "review_queue.csv"
        self._lock = threading.RLock()

    @property
    def ready(self) -> bool:
        return self.queue_path.is_file()

    def _rows(self) -> list[dict[str, str]]:
        return _read_csv(self.queue_path) if self.ready else []

    def _row(self, sample_id: str) -> tuple[int, dict[str, str], list[dict[str, str]]]:
        rows = self._rows()
        for index, row in enumerate(rows):
            if row["sample_id"] == sample_id:
                return index, row, rows
        raise KeyError(sample_id)

    def _annotation_path(self, row: dict[str, str]) -> Path:
        return self.data_root / row["v6_annotation_path"]

    def _image_path(self, row: dict[str, str]) -> Path:
        return Path(row["raw_image_path"])

    def status(self) -> dict[str, Any]:
        rows = self._rows()
        counts = Counter(row["review_state"] for row in rows)
        return {
            "ready": self.ready,
            "total": len(rows),
            "pending_review": counts["pending_review"],
            "confirmed": counts["confirmed"],
            "gate_passed": bool(rows) and counts["confirmed"] == len(rows),
            "required": V6_QUEUE_SIZE,
        }

    def list_samples(self, review_state: str = "pending_review") -> dict[str, Any]:
        rows = self._rows()
        if review_state != "all":
            rows = [row for row in rows if row["review_state"] == review_state]
        return {"items": rows, "total": len(rows), "status": self.status()}

    def detail(self, sample_id: str) -> dict[str, Any]:
        with self._lock:
            _, row, _ = self._row(sample_id)
            return {"sample": row, "annotation": _json(self._annotation_path(row))}

    def image_path(self, sample_id: str) -> Path:
        with self._lock:
            _, row, _ = self._row(sample_id)
            return self._image_path(row)

    def preview_path(self, sample_id: str) -> Path:
        with self._lock:
            _, row, _ = self._row(sample_id)
            path = self.data_root / row["preview_path"]
            if not path.is_file():
                raise FileNotFoundError(path)
            return path

    def review(self, sample_id: str, payload: dict[str, Any]) -> dict[str, Any]:
        with self._lock:
            index, row, rows = self._row(sample_id)
            annotation_path = self._annotation_path(row)
            annotation = _json(annotation_path)
            width = int(annotation["image_width"])
            height = int(annotation["image_height"])
            status = str(annotation["status"])
            contact = _point(payload.get("contact_point"), width, height, "接触点")
            if status != "device":
                contact = None
                state = "unknown"
            else:
                state = "touching_visible" if contact is not None else "not_in_contact"
            tip = contact
            tail = _tail_suggestion(annotation.get("device_bbox"), tip)
            region = "unknown"
            now = _now()
            history = list(annotation.get("review_history") or [])
            history.append({
                "review_revision": annotation.get("review_revision", 0),
                "treatment_tip_point": annotation.get("treatment_tip_point"),
                "tail_endpoint_point": annotation.get("tail_endpoint_point"),
                "contact_state": annotation.get("contact_state"),
                "contact_point": annotation.get("contact_point"),
                "contact_region": annotation.get("contact_region"),
                "superseded_at": now,
            })
            annotation.update({
                "treatment_tip_point": tip,
                "tail_endpoint_point": tail,
                "contact_state": state,
                "contact_point": contact,
                "contact_region": region,
                "review_state": "confirmed",
                "review_revision": int(annotation.get("review_revision", 0)) + 1,
                "review_history": history,
                "reviewed_at": now,
                "updated_at": now,
            })
            _atomic(
                annotation_path,
                (json.dumps(annotation, ensure_ascii=False, indent=2) + "\n").encode("utf-8"),
            )
            preview_path = self.data_root / row["preview_path"]
            self._write_preview(self._image_path(row), annotation, preview_path)
            row.update({"review_state": "confirmed", "updated_at": now})
            rows[index] = row
            _write_csv(self.queue_path, rows, QUEUE_FIELDS)
            return {"ok": True, "message": "V6端点、接触状态和脸部区域已保存", "status": self.status()}

    @staticmethod
    def _write_preview(image_path: Path, annotation: dict[str, Any], output: Path) -> None:
        with Image.open(image_path) as source:
            image = ImageOps.exif_transpose(source).convert("RGB")
        draw = ImageDraw.Draw(image)
        bbox = annotation.get("device_bbox")
        if bbox:
            draw.rectangle(tuple(bbox), outline=(255, 211, 55), width=max(4, min(image.size) // 220))
        colors = {
            "treatment_tip_point": (255, 45, 75),
            "tail_endpoint_point": (60, 130, 255),
            "contact_point": (0, 230, 220),
        }
        radius = max(8, min(image.size) // 80)
        for field, color in colors.items():
            point = annotation.get(field)
            if point:
                x, y = map(float, point)
                draw.ellipse((x - radius, y - radius, x + radius, y + radius), fill=color, outline="white", width=3)
        output.parent.mkdir(parents=True, exist_ok=True)
        image.save(output, quality=94)
