from __future__ import annotations

import asyncio
from pathlib import Path

from fastapi import APIRouter, Request
from fastapi.responses import FileResponse, JSONResponse


router = APIRouter()
WEB_ROOT = Path(__file__).resolve().parents[1] / "web" / "assist_stream"


@router.get("/contact-face-v6/review")
async def review_page() -> FileResponse:
    return FileResponse(WEB_ROOT / "contact_face_v6_simple.html")


@router.get("/v1/contact-face-v6/status")
async def review_status(request: Request) -> JSONResponse:
    try:
        status = await asyncio.to_thread(request.app.state.contact_face_v6.status)
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse({"ok": True, **status})


@router.get("/v1/contact-face-v6/samples")
async def review_samples(request: Request, review_state: str = "pending_review") -> JSONResponse:
    try:
        result = await asyncio.to_thread(
            request.app.state.contact_face_v6.list_samples,
            review_state,
        )
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse({"ok": True, **result})


@router.get("/v1/contact-face-v6/samples/{sample_id}")
async def review_detail(sample_id: str, request: Request) -> JSONResponse:
    try:
        result = await asyncio.to_thread(request.app.state.contact_face_v6.detail, sample_id)
    except KeyError:
        return JSONResponse({"ok": False, "error": "未找到该V6复查样本"}, status_code=404)
    return JSONResponse({"ok": True, **result})


@router.get("/v1/contact-face-v6/samples/{sample_id}/image")
async def review_image(sample_id: str, request: Request):
    try:
        path = await asyncio.to_thread(request.app.state.contact_face_v6.image_path, sample_id)
    except KeyError:
        return JSONResponse({"ok": False, "error": "未找到该V6复查样本"}, status_code=404)
    return FileResponse(path)


@router.get("/v1/contact-face-v6/samples/{sample_id}/preview")
async def review_preview(sample_id: str, request: Request):
    try:
        path = await asyncio.to_thread(request.app.state.contact_face_v6.preview_path, sample_id)
    except KeyError:
        return JSONResponse({"ok": False, "error": "未找到该V6复查样本"}, status_code=404)
    except FileNotFoundError:
        return JSONResponse({"ok": False, "error": "该样本尚未生成V6最终预览"}, status_code=404)
    return FileResponse(path, media_type="image/jpeg")


@router.post("/v1/contact-face-v6/samples/{sample_id}/review")
async def review_save(sample_id: str, request: Request) -> JSONResponse:
    try:
        payload = await request.json()
        if not isinstance(payload, dict):
            raise ValueError("V6复查结果必须是JSON对象")
        result = await asyncio.to_thread(
            request.app.state.contact_face_v6.review,
            sample_id,
            payload,
        )
    except KeyError:
        return JSONResponse({"ok": False, "error": "未找到该V6复查样本"}, status_code=404)
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse(result)
