from collections import Counter
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PROJECT_ROOT))

from scripts.build_contact_face_v6_supplement import (
    DEFAULT_QUOTAS,
    append_supplemental_candidates,
)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--project-root", type=Path, default=PROJECT_ROOT)
    args = parser.parse_args()
    root = args.project_root.resolve()
    queue_path = root / "manifests/contact_face_v6/review_queue.csv"
    data_root = root / "data/contact_face_v6"
    with queue_path.open(encoding="utf-8", newline="") as stream:
        rows = list(csv.DictReader(stream))

    supplemental_rows = [row for row in rows if row.get("supplemental_round")]
    pending = [row for row in supplemental_rows if row["review_state"] != "confirmed"]
    if pending:
        print(json.dumps({
            "result": "BLOCKED",
            "reason": "supplemental_review_pending",
            "pending": len(pending),
        }, indent=2))
        return 2

    confirmed_no_contact: Counter[str] = Counter()
    for row in supplemental_rows:
        annotation = json.loads(
            (data_root / row["v6_annotation_path"]).read_text(encoding="utf-8")
        )
        if annotation.get("status") == "device" and annotation.get("contact_point") is None:
            confirmed_no_contact[row["logical_split"]] += 1

    deficits = {
        split: max(0, target - confirmed_no_contact[split])
        for split, target in DEFAULT_QUOTAS.items()
    }
    deficits = {split: count for split, count in deficits.items() if count}
    if not deficits:
        print(json.dumps({
            "result": "PASS",
            "confirmed_no_contact": dict(confirmed_no_contact),
            "target": DEFAULT_QUOTAS,
        }, indent=2))
        print("CONTACT-FACE-V6 SUPPLEMENTAL REFILL: COMPLETE")
        return 0

    result = append_supplemental_candidates(root, deficits)
    print(json.dumps({
        "result": "READY_FOR_REVIEW",
        "confirmed_no_contact": dict(confirmed_no_contact),
        "target": DEFAULT_QUOTAS,
        "deficits": deficits,
        "new_round": result,
    }, indent=2))
    print("CONTACT-FACE-V6 SUPPLEMENTAL REFILL: READY_FOR_REVIEW")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
